"""Declarações: o pacote (orquestra análises e seções da library), a
inicialização do pacote e a cadeia de declarações de tipo nomeado."""

from g2d.engine.behavior import Behavior, TypeDeclBehavior
from g2d.engine.scope import FunctionScope, TypeParams
from g2d.model import Unsupported
from g2d.services.literals import doc_comment
from g2d.services.naming import member_name, param_name, type_name


HEADER = (
    "// Code generated by g2d from {path}. DO NOT EDIT.\n"
    "// Go aceita código morto, funções/campos não usados e resultados nomeados\n"
    "// não lidos; ponteiros viram tipos anuláveis promovidos pelo fluxo (`!`\n"
    "// redundante).\n"
    "// ignore_for_file: unused_element, unused_field, unused_local_variable, dead_code, unnecessary_non_null_assertion, dead_null_aware_expression, unnecessary_null_comparison\n"
)


class PackageBehavior(Behavior):
    """Pacote Go → library Dart: roda as análises, emite as declarações na
    ordem do fonte e junta as seções (init, mixins, descritores, imports)."""

    def __init__(self, engine):
        super().__init__(engine)
        self.init_behavior = InitBehavior(engine)

    def emit(self):
        decls = [d for f in self.pkg.files for d in f["ast"]["decls"] or []]
        for analysis in self.engine.analyses:
            analysis.run(decls)
        body = []
        for d in decls:
            body += self.engine.guard(self.decl, d)
        for spec, name in self.facts.local_specs:
            body += self.engine.guard(self.type_spec, spec, name, [])
        body += self.synthetic_classes()
        body += self.init_behavior.emit()
        body += self.promoter.mixin_decls
        if self.descriptors.elem_decls:
            body += ["", "// Descritores de tipo (go.Elem) usados por slices, maps e ponteiros."]
            body += self.descriptors.elem_decls
        head = [HEADER.format(path=self.pkg.path)]
        head += self.imports.directives()
        return "\n".join(head + body) + "\n"

    def decl(self, d):
        """Uma declaração de nível de pacote (métodos saem com o tipo)."""
        if d["node"] == "FuncDecl":
            return [] if d["recv"] else [""] + self.functions.func_decl(d)
        if d["tok"] == "type":
            return self.type_decl(d)
        if d["tok"] in ("var", "const"):
            return [""] + self.vars.top_values(d)
        return []

    def type_decl(self, gen):
        out = []
        for spec in gen["specs"]:
            doc = doc_comment(spec["doc"] or (gen["doc"] if len(gen["specs"]) == 1 else None))
            out += self.type_spec(spec, spec["name"]["name"], doc)
        return out

    def type_spec(self, spec, name, doc):
        """Um TypeSpec (de pacote ou içado de função, com `name`)."""
        if spec["typeParams"]:
            kind = self.typesys.underlying(self.pkg.type_at(spec["name"]["$obj"]["type"]))["kind"]
            if kind not in ("struct", "slice", "map", "func", "interface"):
                raise Unsupported(f"generico:{kind}", f"tipo genérico sobre {kind}", spec)
        if spec["assign"]:
            return []  # alias: resolvido pelo goast (tipos já expandidos)
        tidx = spec["name"]["$obj"]["type"]
        t = self.pkg.type_at(tidx)
        u = self.typesys.underlying(t)
        behavior = self.engine.type_decls.find(t, u)
        if behavior is None:
            raise Unsupported(f"tipo-nomeado:{u['kind']}", f"tipo nomeado sobre {u['kind']}", spec)
        return [""] + doc + behavior.emit(spec, name, t, u, tidx)

    def synthetic_classes(self):
        """Classes das structs/interfaces anônimas; emitir uma pode registrar
        outras (campos), então repete até estabilizar. Ordem por índice."""
        out, done = [], set()
        while pending := sorted(set(self.types.synthetics) - done):
            for idx in pending:
                done.add(idx)
                t, name = self.pkg.type_at(idx), self.types.synthetics[idx]
                behavior = self.engine.type_decls.find(t, t)
                if t["kind"] == "struct":
                    out += ["", "/// `" + self.goinfo.go_type_name(t) + "` (struct anônima)."]
                    out += behavior.struct_class(name, t, idx)
                else:
                    out += ["", "/// `" + self.goinfo.go_type_name(t) + "` (interface anônima)."]
                    out += behavior.iface_class(name, t)
        return out


class InitBehavior(Behavior):
    """`$goInit`: variáveis de pacote em ordem de dependência, depois as
    funções init, uma vez só."""

    def emit(self):
        """`$goInit`: variáveis de pacote na ordem de types.Info.InitOrder
        (dependências primeiro) e depois as funções init, em ordem de
        arquivo/fonte, uma vez só. O `main` a chama antes do corpo."""
        from g2d.analysis.color import init_key

        # Cor (g2d/analysis/color.py): `$goInit` vira `Future<void> ... async`
        # se um inicializador, uma função init ou o `$goInit` de uma
        # dependência (no main) suspende; o main o espera.
        is_async = self.concurrency.is_async(init_key(self.pkg))
        self.scope = FunctionScope(sync_reason="init", async_ctx=is_async)
        lines = self.deps_init()
        for entry in self.pkg.init_order:
            spec, idx = self.facts.var_inits[entry[0]]
            lines += self.engine.guard(self.init_entry, spec, idx)
        for decl, name in self.facts.init_funcs.items():
            fn = next(d for f in self.pkg.files for d in f["ast"]["decls"] or []
                      if d["node"] == "FuncDecl" and d["name"]["$obj"]["decl"] == decl)
            aw = "await " if self.concurrency.is_async(self.concurrency.decl_key(fn)) else ""
            lines.append(f"{aw}{name}();")
        self.scope = None
        head = "Future<void> $goInit() async {" if is_async else "void $goInit() {"
        return ["", "bool _$inited = false;", "",
                "/// Inicialização do pacote Go: variáveis em ordem de dependência, depois as funções init.",
                head, "if (_$inited) return;", "_$inited = true;"] + lines + ["}"]

    def deps_init(self):
        """No main, os pacotes do grafo antes (ordem de inicialização do Go:
        global, não por importador). Cada library só se inicializa."""
        if self.pkg.name != "main" or not self.pkg.graph_imports():
            return []
        if self.pkg.init_deps is None:
            spec = self.imports.import_spec(self.pkg.graph_imports()[0])
            raise Unsupported("init-grafo-incompleto",
                              "main sem o grafo de imports no dump: a inicialização das dependências ficaria incompleta",
                              spec)
        from g2d.analysis.color import init_key

        return [("await " if self.concurrency.is_async(("init", dep)) else "")
                + f"{self.imports.qualify(dep, '$goInit')}();" for dep in self.pkg.init_deps]

    def init_entry(self, spec, idx):
        """Um inicializador de variável de pacote (`var a, b = f()` é um só)."""
        names, values = spec["names"], spec["values"]
        if len(values) == len(names):
            return self.init_assign(names[idx], values[idx])
        tmp = self.names.temp()  # var a, b = f() / m[k] / x.(T)
        lines = [f"final {tmp} = {self.operands.multi_value(values[0])};"]
        for i, ident in enumerate(names):
            if ident["name"] != "_":
                lines.append(f"{self.top_var(ident)} = {tmp}.${i + 1};")
        return lines

    def init_assign(self, ident, value):
        if ident["name"] == "_":
            return [f"{self.expr(value)};"]  # `var _ = f()`: só o efeito
        t = self.pkg.type_at(ident["$obj"]["type"])
        return [f"{self.top_var(ident)} = {self.values.coerce(value, t)};"]

    def top_var(self, ident):
        return self.names.top_name(ident["name"], "var", ident["$obj"].get("fold")) + self.names.box_suffix(ident["$obj"])


class StructClass(TypeDeclBehavior):
    """struct Go → classe que estende go.GoStruct (semântica de valor)."""

    def accepts(self, t, u):
        return u["kind"] == "struct"

    def emit(self, spec, name, t, u, tidx):
        tparams = spec["typeParams"] or self.facts.local_tparams.get(id(t))
        return self.struct_class(name, u, tidx, self.functions.type_params(tparams))

    def struct_class(self, go_name, st, tidx, tps=TypeParams()):
        """struct Go → classe que estende go.GoStruct (semântica de valor),
        com os métodos promovidos por embedding (mixins) e `implements`."""
        base_cls = type_name(go_name)
        cls = base_cls + tps.decl
        # Nome com os parâmetros aplicados (sem bounds): Stack<T>.
        tnames = tps.names
        self_t = base_cls + (f"<{', '.join(tnames)}>" if tnames else "")
        t = self.pkg.type_at(tidx)
        if not tnames:  # genérico: sem mixin (o forwarder citaria o parâmetro de tipo à toa)
            self.promoter.declare(t, t.get("methods") or [])
        params, inits, fields, copies, sets, values, names = [], [], [], [], [], [], []
        seen = set()
        for f in st["fields"]:
            if f["name"] == "_":
                # Campo em branco: sem armazenamento (inacessível); sempre zero,
                # então no `$fields` ele só aparece para o `%v`/`%+v` do Go.
                values.append(self.types.zero(f["type"]))
                names.append("'_'")
                continue
            fname = member_name(f["name"])
            pname = param_name(f["name"])
            if not pname or pname in seen:
                raise Unsupported("construtor-ambiguo", f"parâmetro de construtor ambíguo para campo {f['name']}")
            seen.add(pname)
            ft = self.pkg.type_at(f["type"])
            ftype = self.types.dart(ft)
            fields.append(f"{ftype} {fname};")
            names.append(f"'{f['name']}'")
            if ftype.nullable:
                params.append(f"{ftype} {pname}")
                inits.append(f"{fname} = {pname}")
            else:
                params.append(f"{ftype}? {pname}")
                inits.append(f"{fname} = {pname} ?? {self.types.zero(f['type'])}")
            if self.typesys.is_value(ft):
                copies.append(f"{pname}: {fname}.$copy()")
                sets.append(f"{fname}.$set(o.{fname});")
                values.append(fname)
            else:
                copies.append(f"{pname}: {fname}")
                sets.append(f"{fname} = o.{fname};")
                values.append(f"{self.imports.qualify(None, 'Addr')}({fname})" if self.typesys.is_struct_pointer(ft) else fname)
        # Struct genérica: os dicionários vêm primeiro, posicionais.
        dict_params = [f"this.${n}" for n in tnames]
        named = f"{{{', '.join(params)}}}" if params else ""
        ctor = f"{base_cls}({', '.join(p for p in (', '.join(dict_params), named) if p)})"
        ctor += (" : " + ", ".join(inits) if inits else "") + ";"
        fields = [f"final {self.imports.qualify(None, 'Elem')}<{n}> ${n};" for n in tnames] + fields
        dict_args = "".join(f"${n}, " for n in tnames)
        base = self.imports.qualify(None, "GoStruct")
        withs, promoted = self.promoter.promotion(t, st)
        impl = self.goinfo.implements_clause(tidx)
        head = f"class {cls} extends {base}<{self_t}>"
        if withs:
            head += " with " + ", ".join(w for w, _ in withs)
        if impl:
            head += " implements " + ", ".join(impl)
        vm = ", ".join(f"'{n}'" for n in self.goinfo.method_names(t, True))
        pm = ", ".join(f"'{n}'" for n in self.goinfo.method_names(t, False))
        sentinel = [] if tnames else [
            "/// `(*T)(nil)` dentro de uma interface (não é nil no Go).",
            f"static final {cls} $nil = {cls}()..$nilPtr = true;", ""]
        lines = [head + " {", ctor, ""] + sentinel + fields + [
            "",
            "@override",
            f"String get $goType => '{self.goinfo.go_type_name(t)}';",
            "@override",
            f"List<String> get $valueMethods => const [{vm}];",
            "@override",
            f"List<String> get $ptrMethods => const [{pm}];",
        ] + [ln for _, getters in withs for g in getters for ln in ["@override", g]] + promoted + [
            "",
            "@override",
            f"{self_t} $copy() => {self_t}({dict_args}{', '.join(copies)});",
            "",
            "@override",
            f"void $set({self_t} o) {{",
        ] + sets + [
            "}",
            "",
            "@override",
            f"List<Object?> get $fields => [{', '.join(values)}];",
            "",
            "@override",
            f"List<String> get $fieldNames => const [{', '.join(names)}];",
        ] + self.field_types(st)
        for m in self.facts.methods.get(go_name, []):
            lines += [""] + self.functions.func_decl(m)
        return lines + ["}"]

    def field_types(self, st):
        """`$fieldTypes` (nomes Go dos tipos dos campos, para `%#v`), só se
        algum campo não é básico: o valor Dart de slice/map/array/ponteiro/
        interface não diz o próprio tipo Go, e uma struct por valor num campo
        é o mesmo objeto de um ponteiro (só o nome do campo as distingue)."""
        kinds = {self.typesys.underlying(self.pkg.type_at(f["type"]))["kind"] for f in st["fields"]}
        if kinds <= {"basic"}:
            return []
        # Tipo que depende de parâmetro de tipo: sem nome estático ('' = desconhecido).
        types = ", ".join("'" + ("" if self.descriptors.has_tparam(f["type"]) else self.goinfo.sharp_type_name(f["type"]))
                          + "'" for f in st["fields"])
        return ["", "@override", f"List<String> get $fieldTypes => const [{types}];"]


class InterfaceClass(TypeDeclBehavior):
    """interface Go → `abstract mixin class`."""

    def accepts(self, t, u):
        return u["kind"] == "interface"

    def emit(self, spec, name, t, u, tidx):
        tparams = self.functions.type_params(spec["typeParams"] or self.facts.local_tparams.get(id(t)))
        return self.iface_class(name, u, tparams.decl, t)

    def iface_class(self, go_name, u, tparams="", owner=None):
        """interface Go → `abstract mixin class` (métodos abstratos; interfaces
        embutidas em `implements`). Interfaces de restrição (unions) só existem
        como bound de genéricos: nada a emitir. Genérica: `Key<K>` (sem
        dicionários: quem implementa tem os seus)."""
        supers = []
        for e in u["embeddeds"]:
            et = self.pkg.type_at(e)
            if self.typesys.is_universe(et, "comparable"):
                continue  # só restrição (== do Dart); não tem métodos
            if et["kind"] != "named" or self.typesys.underlying(et)["kind"] != "interface":
                return []
            supers.append(self.types.dart(et).non_null())
        head = f"abstract mixin class {type_name(go_name)}{tparams}"
        if supers:
            head += " implements " + ", ".join(supers)
        lines = [head + " {"]
        for m in u["methods"]:
            sig = self.pkg.type_at(m["type"])
            params = ", ".join(f"{self.types.dart(pt)} p{i}" for i, pt in enumerate(sig["params"]))
            ret = self.concurrency.results(self.concurrency.iface_key(owner or u, m["name"]), sig)
            lines.append(f"{ret} {member_name(m['name'])}({params});")
        return lines + ["}"]


class NonStructNamed(TypeDeclBehavior):
    """Base dos tipos nomeados não-struct: a classe de N tem os métodos de
    receptor valor; `*N` é a classe `N$Ptr` (go.PtrView) com os de receptor
    ponteiro, forwarders dos de valor e as interfaces de *N."""

    def split_methods(self, go_name):
        ms = self.facts.methods.get(go_name, [])
        is_ptr = [self.pkg.recv_type(m)["kind"] == "pointer" for m in ms]
        return [m for m, p in zip(ms, is_ptr) if not p], [m for m, p in zip(ms, is_ptr) if p]

    def class_tail(self, t, tidx, value_methods):
        """Membros GoTyped e métodos de receptor valor da classe de N."""
        names = ", ".join(f"'{n}'" for n in self.goinfo.method_names(t, True))
        lines = ["@override", f"String get $goType => '{self.goinfo.go_type_name(t)}';",
                 "@override", f"List<String> get $methods => const [{names}];"]
        for m in value_methods:
            lines += [""] + self.functions.func_decl(m)
        return lines + ["}"]

    def value_implements(self, t, tidx):
        return self.goinfo.implements_clause(tidx, self.goinfo.method_names(t, True))

    def ptr_class(self, t, tidx, ptr_methods, tps=TypeParams()):
        """`final class N$Ptr extends go.PtrView<N>`, se N tem métodos."""
        if not self.typesys.ptr_class(t):
            return []
        base = self.types.dart(t).non_null().name
        n = base + (f"<{', '.join(tps.names)}>" if tps.names else "")  # N ou N<T>
        cls = f"{base}$Ptr"
        impl = self.goinfo.implements_clause(tidx)
        head = f"final class {cls}{tps.decl} extends {self.imports.qualify(None, 'PtrView')}<{n}>"
        names = ", ".join(f"'{m}'" for m in self.goinfo.method_names(t, False))
        lines = ["", "/// `*" + self.goinfo.go_type_name(t) + "`: vista sobre qualquer ponteiro para o valor.",
                 head + (" implements " + ", ".join(impl) if impl else "") + " {",
                 f"{cls}(super.$p);", ""]
        if not tps.names:  # genérico: estático não usa T; a sentinela é criada no uso
            lines += ["/// `(*N)(nil)` dentro de uma interface (não é nil no Go).",
                      f"static final {cls} $nil = {cls}(const {self.imports.qualify(None, 'NilPtr')}<{n}>());", ""]
        # Dicionários do genérico: os do valor apontado (sempre um N, mesmo nil).
        lines += [f"{self.imports.qualify(None, 'Elem')}<{tn}> get ${tn} => $p.value.${tn};" for tn in tps.names]
        lines += ["@override", f"String get $goType => '*{self.goinfo.go_type_name(t)}';",
                  "@override", f"List<String> get $methods => const [{names}];"]
        for m in t["methods"]:
            if m["ptr"]:
                continue
            sig = self.pkg.type_at(m["type"])
            params = ", ".join(f"{self.types.dart(p)} p{i}" for i, p in enumerate(sig["params"]))
            args = ", ".join(f"p{i}" for i in range(len(sig["params"])))
            name = member_name(m["name"])
            ret = self.concurrency.results(self.concurrency.method_key(t, m["name"]), sig)
            lines += ["", f"{ret} {name}({params}) => $p.value.{name}({args});"]
        for m in ptr_methods:
            lines += [""] + self.functions.func_decl(m)
        return lines + ["}"]


class NamedCompositeClass(NonStructNamed):
    """Tipo nomeado sobre slice/map → subclasse de go.Slice/go.GoMap (mesmo
    armazenamento na conversão); sobre func → classe chamável sobre `$f`."""

    def accepts(self, t, u):
        return self.typesys.named_composite(t)

    def emit(self, spec, name, t, u, tidx):
        tparams = spec["typeParams"] or self.facts.local_tparams.get(id(t))
        return self.named_composite_class(spec, name, t, u, tidx, self.functions.type_params(tparams))

    def named_composite_class(self, spec, name, t, u, tidx, tps):
        """Genérico (`type Set[T comparable] map[T]struct{}`): `Set<T>` com os
        dicionários `$T` como primeiros parâmetros do construtor."""
        cls, ud = type_name(name), self.types.dart(u)
        if u["kind"] == "array":
            return self.named_array_class(spec, name, t, u, tidx, cls, ud, tps)
        if not tps.names:  # genérico: sem mixin (o forwarder citaria o parâmetro de tipo à toa)
            self.promoter.declare(t, t.get("methods") or [])
        dict_fields = [f"final {self.imports.qualify(None, 'Elem')}<{n}> ${n};" for n in tps.names]
        dict_params = "".join(f"this.${n}, " for n in tps.names)
        value_ms, ptr_ms = self.split_methods(name)
        impl = self.value_implements(t, tidx) + [self.types.golang("GoTyped")]
        head = cls + tps.decl
        if u["kind"] == "func":
            ft = ud.non_null()
            params = ", ".join(f"{p} p{i}" for i, p in enumerate(ft.params))
            args = ", ".join(f"p{i}" for i in range(len(ft.params)))
            lines = [f"final class {head} implements {', '.join(impl)} {{",
                     f"{cls}({dict_params}this.$f);", ""] + dict_fields + [
                     f"final {ft.as_nullable()} $f;", "",
                     "/// `f == nil`.", "bool get isNil => $f == null;", "",
                     f"{ft.returns} call({params}) => $f!({args});", ""]
        else:
            lines = [f"final class {head} extends {ud} implements {', '.join(impl)} {{",
                     f"{cls}({dict_params}{ud} v) : super.alias(v);", ""] + dict_fields
        return lines + self.class_tail(t, tidx, value_ms) + self.ptr_class(t, tidx, ptr_ms, tps)

    def named_array_class(self, spec, name, t, u, tidx, cls, ud, tps):
        """`type Hash [32]byte` → `final class Hash extends go.GoArray<Uint8>`
        (mesmo armazenamento via `alias`). Array é valor, como struct: o
        objeto é o próprio endereço, então os métodos de receptor ponteiro
        também ficam na classe (sem `N$Ptr`)."""
        if tps.names:
            raise Unsupported("generico:array", "tipo genérico sobre array", spec)
        self.promoter.declare(t, t.get("methods") or [])
        ms = self.facts.methods.get(name, [])
        impl = self.goinfo.implements_clause(tidx)
        vm = ", ".join(f"'{n}'" for n in self.goinfo.method_names(t, True))
        lines = [f"final class {cls} extends {ud}" + (" implements " + ", ".join(impl) if impl else "") + " {",
                 f"{cls}({ud} v) : super.alias(v);", "",
                 "/// `(*T)(nil)` dentro de uma interface (não é nil no Go).",
                 f"static final {cls} $nil = {cls}({self.types.zero(u)})..$nilPtr = true;", "",
                 "@override", f"{cls} $copy() => {cls}(super.$copy());", "",
                 "@override", f"String get $goType => '{self.goinfo.go_type_name(t)}';",
                 "@override", f"List<String> get $methods => const [{vm}];"]
        for m in ms:
            lines += [""] + self.functions.func_decl(m)
        return lines + ["}"]


class NamedClass(NonStructNamed):
    """Tipo nomeado sobre básico → classe sobre a base de operadores."""

    def accepts(self, t, u):
        return u["kind"] == "basic"

    def emit(self, spec, name, t, u, tidx):
        return self.named_class(name, t, u, tidx)

    def named_class(self, go_name, t, u, tidx):
        """Tipo nomeado sobre básico → classe sobre a base de operadores de
        fixed_types (identidade própria em runtime; operadores devolvem o
        tipo nomeado)."""
        self.promoter.declare(t, t.get("methods") or [])
        b = self.typesys.basic(u)
        cls = type_name(go_name)
        store = self.types.golang(b.cls) if b.cls else None
        g = self.types.golang
        if b.cat == "bool":
            # bool nativo não carrega métodos: classe sobre go.GoBool (`$b`).
            base = self.imports.qualify(None, "GoBool")
            body = [f"const {cls}([bool v = false]) : super(v);"]
        elif b.cat == "wint":
            # Herda a representação da largura (Int32Base, Uint64Base...):
            # mesmo caminho rápido do tipo subjacente, sem indireção.
            base = f"{g(('Int' if b.signed else 'Uint') + f'{b.width}Base')}<{cls}>"
            body = [f"{cls}([int v = 0]) : super(v);",
                    f"{cls}.from({g('IntBase')} v) : super.from(v);",
                    f"{cls}.fromBigInt(BigInt v) : super.fromBigInt(v);"]
            if b.width == 64:
                body += [f"{cls}._(super.$hi, super.$lo) : super.raw();",
                         "@override", f"{cls} $make(int hi, int lo) => {cls}._(hi, lo);"]
            else:
                body += ["@override", f"{cls} $make(int v) => {cls}(v);"]
        elif b.cat == "float":
            base = f"{g('FloatBase')}<{cls}>"
            body = [f"{cls}([double v = 0.0]) : _v = {store}(v);",
                    f"final {store} _v;",
                    "@override", "double toDouble() => _v.toDouble();",
                    "@override", f"{cls} $wrapDouble(double v) => {cls}(v);",
                    "@override", f"int get $bits => {32 if b.cls == 'Float32' else 64};"]
        elif b.cat == "string":
            base = f"{g('StringBase')}<{cls}>"
            body = [f"{cls}([{store}? v]) : _v = v ?? {store}();",
                    f"final {store} _v;",
                    "@override", f"{store} get $str => _v;",
                    "@override", f"{cls} $wrapStr({store} s) => {cls}(s);"]
        elif b.cat == "complex":
            # Guarda o complex64/complex128 e delega as operações a ele.
            base = f"{g('ComplexBase')}<{cls}, {store}>"
            body = [f"{cls}([{store}? v]) : $c = v ?? {store}();",
                    "@override", f"final {store} $c;",
                    "@override", f"{cls} $wrapC({store} v) => {cls}(v);"]
        else:
            raise Unsupported(f"tipo-nomeado:{b.cat}", f"tipo nomeado sobre {b.cat}")
        value_ms, ptr_ms = self.split_methods(go_name)
        impl = self.value_implements(t, tidx)
        head = f"final class {cls} extends {base}" + (" implements " + ", ".join(impl) if impl else "")
        return [head + " {"] + body + self.class_tail(t, tidx, value_ms) + self.ptr_class(t, tidx, ptr_ms)
